using System;
using System.Collections;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Xml;

namespace TKSObject
{
    /// <summary>
    /// Xuất DataTable ra Excel theo MẪU CÓ SẴN (.xlsx) dạng "nhóm dòng": mỗi phòng ban 1 hàng nhóm
    /// cộng tổng (SUM), bên dưới là các hàng chi tiết nhân viên, cuối file là phần chân mẫu.
    /// Cơ chế: copy file mẫu ra file đích rồi sửa trực tiếp XML của worksheet bên trong .xlsx (Open XML).
    /// KHÔNG dùng Microsoft.Office.Interop.Excel, KHÔNG dùng Aspose.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Class này KHÔNG biết nghiệp vụ (lương, hợp đồng, chấm công...). Caller phải tự:
    /// 1. Chuẩn bị DataTable đã lọc / sort / thêm cột STT (xem ví dụ bên dưới).
    /// 2. Dựng <see cref="ExcelGroupOptions"/> mô tả đúng file mẫu đang dùng.
    /// 3. Gọi <see cref="Export"/> với đường dẫn mẫu và đường dẫn file đích.
    /// </para>
    /// <para>
    /// Muốn thêm mẫu mới: KHÔNG sửa class này, chỉ thêm file .xlsx vào thư mục mẫu và dựng options khác.
    /// </para>
    /// </remarks>
    /// <example>
    /// <para>Cấu trúc file mẫu .xlsx bắt buộc (ví dụ mẫu bảng lương tháng):</para>
    /// <code>
    /// Hàng 1..9   : tiêu đề / header mẫu (giữ nguyên, exporter không đụng tới)
    /// Hàng 10     : HÀNG NHÓM mẫu  — có sẵn La Mã ở cột A, tên phòng ban, các ô SUM
    /// Hàng 11     : HÀNG CHI TIẾT mẫu — 1 dòng nhân viên, style sẽ được clone cho mọi dòng
    /// Hàng 12+    : CHÂN MẪU (tổng cộng, ngày tháng, chữ ký...) sẽ được dời xuống dưới dữ liệu
    /// </code>
    /// <para>
    /// Exporter sẽ xóa hàng 10 trở xuống, ghi dữ liệu thật, rồi chèn lại phần chân mẫu ở cuối.
    /// Hàng 10 và 11 phải tồn tại đúng số hàng, nếu không sẽ báo "Mẫu Excel cần hàng nhóm ... và hàng chi tiết ...".
    /// </para>
    /// <para>Ví dụ gọi đầy đủ (trích từ frmMonthSalary.ExportExcelMonthSalary):</para>
    /// <code>
    /// private void ExportExcelMonthSalary(int intMau)
    /// {
    ///     DataTable dtbExport = PrepareMonthSalaryOutputData(intMau);
    ///     if (dtbExport == null || dtbExport.Rows.Count == 0)
    ///     {
    ///         MessageManager.Warning("Không có dữ liệu để xuất!");
    ///         return;
    ///     }
    ///
    ///     string strTemplate = Path.Combine(Application.StartupPath, "MauExcel", "HRS", "Mau1_Luong_NhanVien.xlsx");
    ///     string strSaveAs = Path.Combine(Application.StartupPath, "Export", "BangLuong.xlsx");
    ///
    ///     try
    ///     {
    ///         HRS_ExcelGroupExporter.Export(dtbExport, strTemplate, strSaveAs, CreateMyExcelOptions());
    ///     }
    ///     catch (Exception ex)
    ///     {
    ///         ErrorManager.Error("Xuất dữ liệu thất bại: " + ex.Message);
    ///     }
    /// }
    ///
    /// private ExcelGroupOptions CreateMyExcelOptions()
    /// {
    ///     ExcelGroupOptions options = new ExcelGroupOptions();
    ///
    ///     // 1. Vị trí hàng mẫu trong file .xlsx
    ///     options.GroupPrototypeRow = 10;
    ///     options.DetailPrototypeRow = 11;
    ///     options.FooterStartRow = 12;
    ///
    ///     // 2. Gom nhóm theo phòng ban (ưu tiên DepartmentID, thiếu thì dùng DepartmentName)
    ///     options.GroupKeyField = "DepartmentID";
    ///     options.GroupKeyFallbackField = "DepartmentName";
    ///     options.GroupTitleField = "DepartmentName";
    ///
    ///     // 3. Hàng nhóm: số thứ tự La Mã ở cột A, tên phòng ban ở cột C
    ///     options.GroupOrderColumn = "A";
    ///     options.GroupOrderAsRoman = true;
    ///     options.GroupTitleColumn = "C";
    ///
    ///     // 4. Map từng field DataTable vào cột Excel A, B, C... theo đúng thứ tự
    ///     options.DetailFields = new string[] {
    ///         "@GlobalOrder", "@DepartmentOrder", "Fullname", "PositionName", "BankAccount",
    ///         "SalaryRatio", "PositionSub", "OverFrameSub", "TaskSub", "ToxicSub",
    ///         "TeacherSub", "SpecialSub", "DepartmentSub", "InsuSalary", "TotalSalary",
    ///         "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary", "Description"
    ///     };
    ///
    ///     // 5. Hàng nhóm cộng tổng: cột N..S lấy tổng các field tương ứng
    ///     options.TotalColumns = new string[] { "N", "O", "P", "Q", "R", "S" };
    ///     options.TotalFields = new string[] { "InsuSalary", "TotalSalary", "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary" };
    ///
    ///     // 6. Kiểm tra cột bắt buộc (thiếu thì báo lỗi rõ ràng thay vì file Excel trống)
    ///     options.RequiredFields = new string[] { "DepartmentName", "Fullname", "InsuSalary", "TotalSalary" };
    ///
    ///     // 7. Quy tắc riêng cho vài cột
    ///     options.FieldRules = new ExcelFieldRule[] {
    ///         ExcelGroupOptions.Rule("OverFrameSub", 100m, false),   // DB lưu 100 = 100% -> Excel ghi 1.0
    ///         ExcelGroupOptions.Rule("BankAccount", 1m, true)        // ép text để giữ số 0 đầu tài khoản
    ///     };
    ///
    ///     // 8. Ghi text cố định vào ô của mẫu (tiêu đề tháng)
    ///     options.CellWrites = new ExcelCellWrite[] {
    ///         ExcelGroupOptions.Cell(4, "C", "BẢNG LƯƠNG THÁNG " + DateTime.Now.ToString("M/yyyy"))
    ///     };
    ///
    ///     // 9. Thứ tự sort (phòng ban -> chức vụ -> họ tên)
    ///     options.SortFields = new ExcelSortField[] {
    ///         ExcelGroupOptions.Sort("Department_OrderIndex", true, false),
    ///         ExcelGroupOptions.Sort(null, false, true),               // true = sort theo khóa nhóm
    ///         ExcelGroupOptions.Sort("Position_OrderIndex", true, false),
    ///         ExcelGroupOptions.Sort("LastName", false, false),
    ///         ExcelGroupOptions.Sort("FirstName", false, false)
    ///     };
    ///
    ///     return options;
    /// }
    /// </code>
    /// <para>
    /// DataTable truyền vào nên đã được lọc/sort và có cột STT nếu cần. Exporter vẫn sort lại theo
    /// <see cref="ExcelGroupOptions.SortFields"/> và tự đếm STT cho token @GlobalOrder / @DepartmentOrder.
    /// </para>
    /// </example>
    public static class HRS_ExcelGroupExporter
    {
        private const string SpreadsheetNamespace = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        /// <summary>Token trong DetailFields: STT toàn bộ danh sách (exporter tự đếm).</summary>
        private const string TokenGlobalOrder = "@GlobalOrder";
        /// <summary>Token trong DetailFields: STT trong phòng ban (exporter tự đếm lại từ 1 mỗi nhóm).</summary>
        private const string TokenDepartmentOrder = "@DepartmentOrder";

        /// <summary>
        /// Xuất dữ liệu ra Excel theo mẫu nhóm dòng. Đây là hàm duy nhất caller cần gọi.
        /// </summary>
        /// <param name="data">Dữ liệu nguồn; mỗi DataRow = 1 dòng chi tiết, gom nhóm theo <see cref="ExcelGroupOptions.GroupKeyField"/>.</param>
        /// <param name="templatePath">Đường dẫn file mẫu .xlsx (bắt buộc tồn tại).</param>
        /// <param name="outputPath">Đường dẫn file kết quả; thư mục cha được tạo tự động nếu chưa có.</param>
        /// <param name="options">Cấu hình map cột / nhóm / tổng / sort cho đúng mẫu. Xem <see cref="ExcelGroupOptions"/>.</param>
        /// <exception cref="ArgumentNullException">data hoặc options null.</exception>
        /// <exception cref="FileNotFoundException">Không tìm thấy file mẫu.</exception>
        /// <exception cref="ArgumentException">DataTable rỗng, thiếu cột bắt buộc, hoặc chưa gán DetailFields.</exception>
        /// <exception cref="InvalidDataException">File mẫu thiếu hàng nhóm / hàng chi tiết.</exception>
        /// <remarks>
        /// Nếu lỗi giữa chừng, file output đang ghi dở sẽ bị xóa để tránh mở ra file Excel hỏng.
        /// </remarks>
        public static void Export(DataTable data, string templatePath, string outputPath, ExcelGroupOptions options)
        {
            if (data == null) throw new ArgumentNullException("data");
            if (options == null) throw new ArgumentNullException("options");
            if (!File.Exists(templatePath)) throw new FileNotFoundException("Không tìm thấy mẫu Excel.", templatePath);
            if (data.Rows.Count == 0) throw new ArgumentException("Không có dữ liệu để xuất.", "data");
            ValidateColumns(data, options);
            if (options.DetailFields == null || options.DetailFields.Length == 0)
                throw new ArgumentException("DetailFields chưa cấu hình.", "options");

            string folder = Path.GetDirectoryName(outputPath);
            if (!String.IsNullOrEmpty(folder)) Directory.CreateDirectory(folder);
            File.Copy(templatePath, outputPath, true);
            try
            {
                using (IDisposable package = (IDisposable)OpenPackage(outputPath))
                {
                    Uri sheetUri = new Uri(options.WorksheetPartUri, UriKind.Relative);
                    object sheetPart = PackageGetPart(package, sheetUri);
                    XmlDocument sheet = LoadXml(sheetPart);
                    FillSheet(sheet, data, options);
                    SaveXml(sheetPart, sheet);
                    UpdateWorkbook(package);
                }
            }
            catch
            {
                try { File.Delete(outputPath); }
                catch (IOException) { }
                catch (UnauthorizedAccessException) { }
                throw;
            }
        }

        /// <summary>Kiểm tra các cột bắt buộc trong <see cref="ExcelGroupOptions.RequiredFields"/> có tồn tại trong DataTable.</summary>
        private static void ValidateColumns(DataTable data, ExcelGroupOptions options)
        {
            if (options.RequiredFields == null) return;
            foreach (string field in options.RequiredFields)
                if (!data.Columns.Contains(field))
                    throw new ArgumentException("Dữ liệu thiếu cột " + field + ".", "data");
        }

        /// <summary>
        /// Trái tim của exporter: xóa hàng mẫu từ hàng nhóm trở xuống, ghi hàng nhóm + hàng chi tiết
        /// theo dữ liệu, chèn lại phần chân mẫu, rồi cập nhật dimension và số lượng merge cell.
        /// </summary>
        private static void FillSheet(XmlDocument sheet, DataTable data, ExcelGroupOptions options)
        {
            int footerStartRow = options.FooterStartRow > 0
                ? options.FooterStartRow
                : options.DetailPrototypeRow + 1;
            XmlNamespaceManager ns = new XmlNamespaceManager(sheet.NameTable);
            ns.AddNamespace("m", SpreadsheetNamespace);
            XmlElement sheetData = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:sheetData", ns);
            string groupRowRef = options.GroupPrototypeRow.ToString(CultureInfo.InvariantCulture);
            string detailRowRef = options.DetailPrototypeRow.ToString(CultureInfo.InvariantCulture);
            XmlElement groupPrototype = (XmlElement)sheetData.SelectSingleNode("m:row[@r='" + groupRowRef + "']", ns);
            XmlElement detailPrototype = (XmlElement)sheetData.SelectSingleNode("m:row[@r='" + detailRowRef + "']", ns);
            if (groupPrototype == null || detailPrototype == null)
                throw new InvalidDataException("Mẫu Excel cần hàng nhóm " + groupRowRef + " và hàng chi tiết " + detailRowRef + ".");
            List<XmlElement> footerRows = new List<XmlElement>();
            foreach (XmlNode row in sheetData.SelectNodes("m:row", ns))
                if (Int32.Parse(row.Attributes["r"].Value, CultureInfo.InvariantCulture) >= footerStartRow)
                    footerRows.Add((XmlElement)row.CloneNode(true));
            List<string[]> footerMerges = ReadFooterMerges(sheet, ns, footerStartRow);
            List<string[]> groupMerges = ReadGroupMerges(sheet, ns, options.GroupPrototypeRow);
            List<XmlNode> oldRows = new List<XmlNode>();
            foreach (XmlNode row in sheetData.SelectNodes("m:row", ns))
                if (Int32.Parse(row.Attributes["r"].Value, CultureInfo.InvariantCulture) >= options.GroupPrototypeRow)
                    oldRows.Add(row);
            foreach (XmlNode row in oldRows) sheetData.RemoveChild(row);
            List<DataRow> rows = new List<DataRow>();
            foreach (DataRow row in data.Rows)
                if (row.RowState != DataRowState.Deleted) rows.Add(row);
            rows.Sort(delegate(DataRow left, DataRow right) { return CompareRows(left, right, options); });
            int currentRow = options.GroupPrototypeRow;
            int globalOrder = 0;
            int groupOrder = 0;
            int position = 0;
            string[] fields = options.DetailFields;
            string[] totalColumns = options.TotalColumns ?? new string[0];
            string[] totalFields = options.TotalFields ?? new string[0];
            while (position < rows.Count)
            {
                int end = position + 1;
                string groupKey = BuildGroupKey(rows[position], options);
                while (end < rows.Count && BuildGroupKey(rows[end], options) == groupKey) end++;
                groupOrder++;
                int groupRowNumber = currentRow++;
                XmlElement groupRow = CloneRow(groupPrototype, groupRowNumber);
                string orderText = options.GroupOrderAsRoman
                    ? Roman(groupOrder)
                    : groupOrder.ToString(CultureInfo.InvariantCulture);
                SetText(groupRow, options.GroupOrderColumn, groupRowNumber, orderText);
                string titleField = String.IsNullOrEmpty(options.GroupTitleField) ? "DepartmentName" : options.GroupTitleField;
                SetText(groupRow, options.GroupTitleColumn, groupRowNumber, TextValue(rows[position], titleField));
                int firstDetail = currentRow;
                for (int i = position; i < end; i++)
                {
                    globalOrder++;
                    int departmentOrder = i - position + 1;
                    XmlElement detailRow = CloneRow(detailPrototype, currentRow);
                    for (int col = 0; col < fields.Length; col++)
                    {
                        string addressColumn = ColumnName(col + 1);
                        string field = fields[col];
                        if (field == TokenGlobalOrder)
                            SetNumber(detailRow, addressColumn, currentRow, globalOrder);
                        else if (field == TokenDepartmentOrder)
                            SetNumber(detailRow, addressColumn, currentRow, departmentOrder);
                        else if (data.Columns.Contains(field) && rows[i][field] != DBNull.Value)
                            WriteDetailField(detailRow, addressColumn, currentRow, rows[i][field], field, options);
                    }
                    sheetData.AppendChild(detailRow);
                    currentRow++;
                }
                for (int i = 0; i < totalColumns.Length && i < totalFields.Length; i++)
                {
                    decimal total = 0m;
                    for (int detail = position; detail < end; detail++)
                        if (rows[detail][totalFields[i]] != DBNull.Value)
                            total += Convert.ToDecimal(rows[detail][totalFields[i]], CultureInfo.InvariantCulture);
                    SetFormula(groupRow, totalColumns[i], groupRowNumber,
                        "SUM(" + totalColumns[i] + firstDetail + ":" + totalColumns[i] + (currentRow - 1) + ")", total);
                }
                sheetData.InsertBefore(groupRow, sheetData.SelectSingleNode("m:row[@r='" + firstDetail + "']", ns));
                AddGroupMerges(sheet, ns, groupMerges, groupRowNumber);
                position = end;
            }
            int footerOffset = currentRow - footerStartRow;
            int lastRow = currentRow - 1;
            foreach (XmlElement footerRow in footerRows)
            {
                int rowNumber = Int32.Parse(footerRow.GetAttribute("r"), CultureInfo.InvariantCulture) + footerOffset;
                footerRow.SetAttribute("r", rowNumber.ToString(CultureInfo.InvariantCulture));
                foreach (XmlNode node in footerRow.ChildNodes)
                {
                    XmlElement cell = node as XmlElement;
                    if (cell != null && cell.LocalName == "c")
                        cell.SetAttribute("r", ColumnLetters(cell.GetAttribute("r")) + rowNumber);
                }
                sheetData.AppendChild(footerRow);
                lastRow = rowNumber;
            }
            AddFooterMerges(sheet, ns, footerMerges, footerOffset);
            if (options.CellWrites != null)
            {
                foreach (ExcelCellWrite write in options.CellWrites)
                {
                    if (write == null) continue;
                    XmlElement rowElement = (XmlElement)sheetData.SelectSingleNode(
                        "m:row[@r='" + write.Row + "']", ns);
                    if (rowElement != null)
                        SetText(rowElement, write.Column, write.Row, write.Text ?? "");
                }
            }
            XmlElement dimension = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:dimension", ns);
            if (dimension != null)
            {
                string[] dimensionAddresses = dimension.GetAttribute("ref").Split(':');
                string existingEnd = dimensionAddresses[dimensionAddresses.Length - 1];
                int lastColumn = Math.Max(fields.Length, ColumnIndex(ColumnLetters(existingEnd)));
                dimension.SetAttribute("ref", "A1:" + ColumnName(lastColumn) + lastRow);
            }
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges != null) merges.SetAttribute("count", merges.ChildNodes.Count.ToString(CultureInfo.InvariantCulture));
        }

        /// <summary>Ghi 1 ô chi tiết: áp rule (chia hệ số / ép text) nếu có, ngược lại tự nhận số hay chuỗi.</summary>
        private static void WriteDetailField(XmlElement detailRow, string addressColumn, int currentRow, object value, string field, ExcelGroupOptions options)
        {
            ExcelFieldRule rule = FindRule(options, field);
            bool forceText = rule != null && rule.ForceText;
            if (rule != null && rule.DivideBy > 1m)
            {
                decimal number = Convert.ToDecimal(value, CultureInfo.InvariantCulture) / rule.DivideBy;
                SetNumber(detailRow, addressColumn, currentRow, number);
                return;
            }
            SetDataValue(detailRow, addressColumn, currentRow, value, forceText);
        }

        /// <summary>Tìm rule cấu hình cho 1 field, không có thì trả null.</summary>
        private static ExcelFieldRule FindRule(ExcelGroupOptions options, string field)
        {
            if (options.FieldRules == null) return null;
            foreach (ExcelFieldRule rule in options.FieldRules)
                if (rule != null && rule.Field == field) return rule;
            return null;
        }

        /// <summary>So sánh 2 dòng theo danh sách <see cref="ExcelGroupOptions.SortFields"/> (dừng ở field khác nhau đầu tiên).</summary>
        private static int CompareRows(DataRow left, DataRow right, ExcelGroupOptions options)
        {
            if (options.SortFields == null || options.SortFields.Length == 0) return 0;
            foreach (ExcelSortField sort in options.SortFields)
            {
                if (sort == null) continue;
                int result = 0;
                if (sort.UseGroupKey)
                    result = String.Compare(BuildGroupKey(left, options), BuildGroupKey(right, options), StringComparison.OrdinalIgnoreCase);
                else if (String.IsNullOrEmpty(sort.Field))
                    continue;
                else if (sort.Numeric)
                    result = IntegerValue(left, sort.Field, Int32.MaxValue)
                        .CompareTo(IntegerValue(right, sort.Field, Int32.MaxValue));
                else
                    result = String.Compare(TextValue(left, sort.Field), TextValue(right, sort.Field), StringComparison.CurrentCultureIgnoreCase);
                if (result != 0) return result;
            }
            return 0;
        }

        /// <summary>Khóa gom nhóm: ưu tiên GroupKeyField ("ID:xxx"), thiếu thì GroupKeyFallbackField ("NAME:xxx").</summary>
        private static string BuildGroupKey(DataRow row, ExcelGroupOptions options)
        {
            if (!String.IsNullOrEmpty(options.GroupKeyField)
                && row.Table.Columns.Contains(options.GroupKeyField)
                && row[options.GroupKeyField] != DBNull.Value)
                return "ID:" + Convert.ToString(row[options.GroupKeyField], CultureInfo.InvariantCulture);
            string fallback = options.GroupKeyFallbackField ?? "";
            return "NAME:" + TextValue(row, fallback);
        }

        /// <summary>Đọc merge cell của hàng nhóm mẫu để nhân bản cho mọi hàng nhóm; đồng thời xóa merge từ hàng mẫu trở xuống.</summary>
        private static List<string[]> ReadGroupMerges(XmlDocument sheet, XmlNamespaceManager ns, int groupPrototypeRow)
        {
            List<string[]> prototypeMerges = new List<string[]>();
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges == null) return prototypeMerges;
            List<XmlNode> remove = new List<XmlNode>();
            foreach (XmlNode merge in merges.ChildNodes)
            {
                string[] addresses = merge.Attributes["ref"].Value.Split(':');
                int first = RowNumber(addresses[0]);
                int last = RowNumber(addresses[addresses.Length - 1]);
                if (first == groupPrototypeRow && last == groupPrototypeRow)
                    prototypeMerges.Add(new string[] { ColumnLetters(addresses[0]), ColumnLetters(addresses[addresses.Length - 1]) });
                if (last >= groupPrototypeRow) remove.Add(merge);
            }
            foreach (XmlNode merge in remove) merges.RemoveChild(merge);
            return prototypeMerges;
        }

        /// <summary>Đọc merge cell thuộc phần chân mẫu (trước khi chân mẫu bị dời xuống theo dữ liệu).</summary>
        private static List<string[]> ReadFooterMerges(XmlDocument sheet, XmlNamespaceManager ns, int footerStartRow)
        {
            List<string[]> footerMerges = new List<string[]>();
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges == null) return footerMerges;
            foreach (XmlNode merge in merges.ChildNodes)
            {
                string[] addresses = merge.Attributes["ref"].Value.Split(':');
                if (RowNumber(addresses[0]) >= footerStartRow)
                    footerMerges.Add(addresses);
            }
            return footerMerges;
        }

        /// <summary>Tạo lại merge cell của chân mẫu ở vị trí mới (đã dời xuống offset hàng).</summary>
        private static void AddFooterMerges(XmlDocument sheet, XmlNamespaceManager ns, List<string[]> footerMerges, int offset)
        {
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges == null) return;
            foreach (string[] addresses in footerMerges)
            {
                XmlElement merge = sheet.CreateElement("mergeCell", SpreadsheetNamespace);
                merge.SetAttribute("ref", ColumnLetters(addresses[0]) + (RowNumber(addresses[0]) + offset)
                    + ":" + ColumnLetters(addresses[addresses.Length - 1])
                    + (RowNumber(addresses[addresses.Length - 1]) + offset));
                merges.AppendChild(merge);
            }
        }

        /// <summary>Tạo merge cell cho 1 hàng nhóm mới theo khuôn merge của hàng nhóm mẫu.</summary>
        private static void AddGroupMerges(XmlDocument sheet, XmlNamespaceManager ns, List<string[]> groupMerges, int row)
        {
            if (groupMerges.Count == 0) return;
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            foreach (string[] columns in groupMerges)
            {
                XmlElement merge = sheet.CreateElement("mergeCell", SpreadsheetNamespace);
                merge.SetAttribute("ref", columns[0] + row + ":" + columns[1] + row);
                merges.AppendChild(merge);
            }
        }

        /// <summary>Clone 1 hàng mẫu: đổi số hàng, đổi địa chỉ ô, xóa nội dung nhưng GIỮ style/format của ô.</summary>
        private static XmlElement CloneRow(XmlElement prototype, int row)
        {
            XmlElement copy = (XmlElement)prototype.CloneNode(true);
            copy.SetAttribute("r", row.ToString(CultureInfo.InvariantCulture));
            foreach (XmlNode node in copy.ChildNodes)
            {
                XmlElement cell = node as XmlElement;
                if (cell == null || cell.LocalName != "c") continue;
                cell.SetAttribute("r", ColumnLetters(cell.GetAttribute("r")) + row);
                while (cell.HasChildNodes) cell.RemoveChild(cell.FirstChild);
                cell.RemoveAttribute("t");
            }
            return copy;
        }

        /// <summary>
        /// Ghi giá trị vào ô: số thì ghi dạng số, còn lại ghi dạng chuỗi.
        /// </summary>
        /// <param name="forceText">True (ô tài khoản ngân hàng) — luôn ghi chuỗi để Excel không bỏ số 0 đầu.</param>
        private static void SetDataValue(XmlElement row, string col, int rowNumber, object value, bool forceText)
        {
            if (!forceText && value is IConvertible && !(value is string) && !(value is DateTime))
            {
                try
                {
                    decimal number = Convert.ToDecimal(value, CultureInfo.InvariantCulture);
                    SetNumber(row, col, rowNumber, number);
                    return;
                }
                catch (InvalidCastException) { }
                catch (FormatException) { }
            }
            SetText(row, col, rowNumber, Convert.ToString(value, CultureInfo.CurrentCulture));
        }

        /// <summary>Ghi ô dạng số.</summary>
        private static void SetNumber(XmlElement row, string col, int rowNumber, decimal value)
        {
            XmlElement cell = GetCell(row, col, rowNumber);
            ClearCellContent(cell);
            XmlElement number = cell.OwnerDocument.CreateElement("v", SpreadsheetNamespace);
            number.InnerText = value.ToString(CultureInfo.InvariantCulture);
            cell.AppendChild(number);
        }

        /// <summary>Ghi ô dạng chuỗi (inlineStr) — dùng cho tên, mô tả, số tài khoản.</summary>
        private static void SetText(XmlElement row, string col, int rowNumber, string value)
        {
            XmlElement cell = GetCell(row, col, rowNumber);
            ClearCellContent(cell);
            cell.SetAttribute("t", "inlineStr");
            XmlElement inline = cell.OwnerDocument.CreateElement("is", SpreadsheetNamespace);
            XmlElement text = cell.OwnerDocument.CreateElement("t", SpreadsheetNamespace);
            text.InnerText = value ?? "";
            inline.AppendChild(text);
            cell.AppendChild(inline);
        }

        /// <summary>Ghi ô vừa có công thức (f) vừa có giá trị tính sẵn (v) — dùng cho dòng SUM của hàng nhóm.</summary>
        private static void SetFormula(XmlElement row, string col, int rowNumber, string formula, decimal value)
        {
            XmlElement cell = GetCell(row, col, rowNumber);
            ClearCellContent(cell);
            XmlElement f = cell.OwnerDocument.CreateElement("f", SpreadsheetNamespace);
            f.InnerText = formula;
            XmlElement v = cell.OwnerDocument.CreateElement("v", SpreadsheetNamespace);
            v.InnerText = value.ToString(CultureInfo.InvariantCulture);
            cell.AppendChild(f);
            cell.AppendChild(v);
        }

        /// <summary>Xóa nội dung 1 ô (giữ lại thuộc tính style s).</summary>
        private static void ClearCellContent(XmlElement cell)
        {
            while (cell.HasChildNodes) cell.RemoveChild(cell.FirstChild);
            cell.RemoveAttribute("t");
        }

        /// <summary>
        /// Lấy ô theo cột + hàng; chưa có thì tạo mới và chèn đúng vị trí thứ tự cột để XML luôn hợp lệ.
        /// </summary>
        private static XmlElement GetCell(XmlElement row, string col, int rowNumber)
        {
            string address = col + rowNumber;
            foreach (XmlNode node in row.ChildNodes)
            {
                XmlElement cell = node as XmlElement;
                if (cell != null && cell.LocalName == "c" && cell.GetAttribute("r") == address) return cell;
            }
            XmlElement created = row.OwnerDocument.CreateElement("c", SpreadsheetNamespace);
            created.SetAttribute("r", address);
            int target = ColumnIndex(col);
            foreach (XmlNode node in row.ChildNodes)
            {
                XmlElement cell = node as XmlElement;
                if (cell != null && cell.LocalName == "c" && ColumnIndex(ColumnLetters(cell.GetAttribute("r"))) > target)
                {
                    row.InsertBefore(created, cell);
                    return created;
                }
            }
            row.AppendChild(created);
            return created;
        }

        /// <summary>Đọc value dạng chuỗi; cột không tồn tại hoặc NULL thì trả "".</summary>
        private static string TextValue(DataRow row, string name)
        {
            return row.Table.Columns.Contains(name) && row[name] != DBNull.Value
                ? Convert.ToString(row[name], CultureInfo.CurrentCulture) : "";
        }

        /// <summary>Đọc value dạng số nguyên; cột không tồn tại hoặc NULL thì trả fallback (thường Int32.MaxValue để đẩy xuống cuối).</summary>
        private static int IntegerValue(DataRow row, string name, int fallback)
        {
            return row.Table.Columns.Contains(name) && row[name] != DBNull.Value
                ? Convert.ToInt32(row[name], CultureInfo.InvariantCulture) : fallback;
        }

        /// <summary>Đổi số thứ tự nhóm thành số La Mã (1 -> I, 2 -> II, 4 -> IV...). Vượt 3999 thì trả số thường.</summary>
        private static string Roman(int value)
        {
            if (value > 3999) return value.ToString(CultureInfo.InvariantCulture);
            int[] numbers = { 1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1 };
            string[] letters = { "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I" };
            System.Text.StringBuilder text = new System.Text.StringBuilder();
            for (int i = 0; i < numbers.Length; i++)
                while (value >= numbers[i]) { text.Append(letters[i]); value -= numbers[i]; }
            return text.ToString();
        }

        /// <summary>Đổi số thứ tự cột thành tên cột Excel (1 -> A, 27 -> AA).</summary>
        private static string ColumnName(int index)
        {
            string result = "";
            while (index > 0) { index--; result = (char)('A' + index % 26) + result; index /= 26; }
            return result;
        }

        /// <summary>Đổi tên cột Excel thành số thứ tự (A -> 1, AA -> 27).</summary>
        private static int ColumnIndex(string letters)
        {
            int index = 0;
            foreach (char c in letters) index = index * 26 + c - 'A' + 1;
            return index;
        }

        /// <summary>Tách phần chữ cái (tên cột) khỏi địa chỉ ô. "AB12" -> "AB".</summary>
        private static string ColumnLetters(string address)
        {
            int i = 0;
            while (i < address.Length && Char.IsLetter(address[i])) i++;
            return address.Substring(0, i);
        }

        /// <summary>Tách phần số hàng khỏi địa chỉ ô. "AB12" -> 12.</summary>
        private static int RowNumber(string address)
        {
            int i = 0;
            while (i < address.Length && Char.IsLetter(address[i])) i++;
            return Int32.Parse(address.Substring(i), CultureInfo.InvariantCulture);
        }

        /// <summary>Đọc XML của 1 part trong gói Open XML.</summary>
        private static XmlDocument LoadXml(object part)
        {
            XmlDocument doc = new XmlDocument();
            doc.XmlResolver = null;
            using (Stream stream = (Stream)Call(part, "GetStream",
                new Type[] { typeof(FileMode), typeof(FileAccess) }, FileMode.Open, FileAccess.Read))
                doc.Load(stream);
            return doc;
        }

        /// <summary>Ghi XML trở lại part trong gói Open XML.</summary>
        private static void SaveXml(object part, XmlDocument doc)
        {
            using (Stream stream = (Stream)Call(part, "GetStream",
                new Type[] { typeof(FileMode), typeof(FileAccess) }, FileMode.Create, FileAccess.Write))
                doc.Save(stream);
        }

        /// <summary>
        /// Bật tính lại công thức khi mở file (calcMode=auto, fullCalcOnLoad=1) và xóa calcChain cũ.
        /// Cần thiết vì exporter đã chèn/xóa hàng nên calcChain của mẫu không còn đúng.
        /// </summary>
        private static void UpdateWorkbook(object package)
        {
            object workbookPart = PackageGetPart(package, new Uri("/xl/workbook.xml", UriKind.Relative));
            XmlDocument workbook = LoadXml(workbookPart);
            XmlNamespaceManager ns = new XmlNamespaceManager(workbook.NameTable);
            ns.AddNamespace("m", SpreadsheetNamespace);
            XmlElement calculation = (XmlElement)workbook.SelectSingleNode("/m:workbook/m:calcPr", ns);
            if (calculation == null)
            {
                calculation = workbook.CreateElement("calcPr", SpreadsheetNamespace);
                workbook.DocumentElement.AppendChild(calculation);
            }
            calculation.SetAttribute("calcMode", "auto");
            calculation.SetAttribute("fullCalcOnLoad", "1");
            calculation.SetAttribute("forceFullCalc", "1");
            SaveXml(workbookPart, workbook);
            Uri chainUri = new Uri("/xl/calcChain.xml", UriKind.Relative);
            if ((bool)Call(package, "PartExists", new Type[] { typeof(Uri) }, chainUri))
            {
                List<string> relationIds = new List<string>();
                foreach (object relation in (IEnumerable)Call(workbookPart, "GetRelationships", Type.EmptyTypes))
                {
                    Type relationType = relation.GetType();
                    string kind = (string)relationType.GetProperty("RelationshipType").GetValue(relation, null);
                    if (kind.EndsWith("/calcChain", StringComparison.Ordinal))
                        relationIds.Add((string)relationType.GetProperty("Id").GetValue(relation, null));
                }
                foreach (string id in relationIds)
                    Call(workbookPart, "DeleteRelationship", new Type[] { typeof(string) }, id);
                Call(package, "DeletePart", new Type[] { typeof(Uri) }, chainUri);
            }
        }

        /// <summary>
        /// Mở file .xlsx như 1 gói Open XML bằng System.IO.Packaging (WindowsBase của .NET 4).
        /// Gọi qua reflection vì project VS2010 không reference WindowsBase lúc compile.
        /// </summary>
        private static object OpenPackage(string path)
        {
            Type type = Type.GetType("System.IO.Packaging.Package, WindowsBase, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35", true);
            MethodInfo open = type.GetMethod("Open", new Type[] {
                typeof(string), typeof(FileMode), typeof(FileAccess) });
            return open.Invoke(null, new object[] { path, FileMode.Open, FileAccess.ReadWrite });
        }

        /// <summary>Lấy 1 part (ví dụ sheet1.xml) trong gói Open XML.</summary>
        private static object PackageGetPart(object package, Uri uri)
        {
            return Call(package, "GetPart", new Type[] { typeof(Uri) }, uri);
        }

        /// <summary>Gọi method qua reflection; ném lại exception gốc thay vì TargetInvocationException bọc ngoài.</summary>
        private static object Call(object target, string method, Type[] parameters, params object[] args)
        {
            MethodInfo member = target.GetType().GetMethod(method, parameters);
            if (member == null) throw new MissingMethodException(target.GetType().FullName, method);
            try { return member.Invoke(target, args); }
            catch (TargetInvocationException ex)
            {
                if (ex.InnerException != null) throw ex.InnerException;
                throw;
            }
        }
    }
    /// <summary>
    /// Cấu hình cho <see cref="HRS_ExcelGroupExporter"/>. Caller gán theo đúng file mẫu .xlsx đang dùng.
    /// Xem ví dụ đầy đủ trong doc của <see cref="HRS_ExcelGroupExporter"/>.
    /// </summary>
    public sealed class ExcelGroupOptions
    {
        /// <summary>Số hàng của HÀNG NHÓM mẫu trong file .xlsx (thường 10). Bắt buộc đúng.</summary>
        public int GroupPrototypeRow = 10;
        /// <summary>Số hàng của HÀNG CHI TIẾT mẫu trong file .xlsx (thường 11). Bắt buộc đúng.</summary>
        public int DetailPrototypeRow = 11;
        /// <summary>Hàng bắt đầu phần CHÂN MẪU (thường 12). Để 0 thì exporter tự lấy DetailPrototypeRow + 1.</summary>
        public int FooterStartRow = 12;
        /// <summary>Tên cột DataTable dùng gom nhóm (ưu tiên). Ví dụ "DepartmentID".</summary>
        public string GroupKeyField;
        /// <summary>Tên cột DataTable gom nhóm dự phòng khi GroupKeyField thiếu/NULL. Ví dụ "DepartmentName".</summary>
        public string GroupKeyFallbackField;
        /// <summary>Tên cột DataTable hiển thị làm tiêu đề phòng ban trên hàng nhóm. Ví dụ "DepartmentName".</summary>
        public string GroupTitleField;
        /// <summary>Cột Excel chứa tên phòng ban trên hàng nhóm. Mẫu 1 dùng "C", mẫu 2/3 dùng "B".</summary>
        public string GroupTitleColumn = "B";
        /// <summary>Cột Excel chứa số thứ tự nhóm. Thường "A".</summary>
        public string GroupOrderColumn = "A";
        /// <summary>True: STT nhóm ghi La Mã (I, II, III). False: ghi số thường (1, 2, 3).</summary>
        public bool GroupOrderAsRoman = true;
        /// <summary>
        /// Map cột Excel theo thứ tự: phần tử [0] ghi vào cột A, [1] vào cột B, [2] vào cột C...
