        public string[] RequiredFields;
        /// <summary>Rule riêng cho từng cột (chia hệ số %, ép text). Xem <see cref="ExcelFieldRule"/>.</summary>
        public ExcelFieldRule[] FieldRules;
        /// <summary>Các ô ghi text cố định trên mẫu (tiêu đề tháng, header). Xem <see cref="ExcelCellWrite"/>.</summary>
        public ExcelCellWrite[] CellWrites;
