        /// <param name="bolUseGroupKey">True: sort theo khóa gom nhóm (GroupKeyField/Fallback) thay vì 1 cột.</param>
        public static ExcelSortField Sort(string strField, bool bolNumeric, bool bolUseGroupKey)
        {
            ExcelSortField sort = new ExcelSortField();
            sort.Field = strField;
            sort.Numeric = bolNumeric;
            sort.UseGroupKey = bolUseGroupKey;
            return sort;
        }

        /// <summary>Tạo 1 rule ghi ô.</summary>
        /// <param name="strField">Tên cột DataTable áp rule.</param>
        /// <param name="decDivideBy">Chia trước khi ghi. DB lưu 100 = 100% thì truyền 100m; truyền 1m = không chia.</param>
        /// <param name="bolForceText">True: luôn ghi dạng text (giữ số 0 đầu, ví dụ số tài khoản).</param>
        public static ExcelFieldRule Rule(string strField, decimal decDivideBy, bool bolForceText)
        {
            ExcelFieldRule rule = new ExcelFieldRule();
            rule.Field = strField;
            rule.DivideBy = decDivideBy;
            rule.ForceText = bolForceText;
            return rule;
        }

        /// <summary>Tạo 1 ô ghi text cố định trên mẫu (ô phải có sẵn trong file mẫu, exporter chỉ ghi đè nội dung).</summary>
        /// <param name="intRow">Số hàng Excel (1-based).</param>
        /// <param name="strColumn">Tên cột Excel (A, B, C...).</param>
