        public static ExcelCellWrite Cell(int intRow, string strColumn, string strText)
        {
            ExcelCellWrite cell = new ExcelCellWrite();
            cell.Row = intRow;
            cell.Column = strColumn;
            cell.Text = strText;
            return cell;
        }
