    /// <summary>Rule ghi ô cho 1 field: chia hệ số (phần trăm) và/hoặc ép dạng text.</summary>
    public sealed class ExcelFieldRule
    {
        /// <summary>Tên cột DataTable áp rule.</summary>
        public string Field;
        /// <summary>Chia giá trị trước khi ghi. &gt; 1 thì chia (100 = phần trăm); = 1 thì giữ nguyên.</summary>
        public decimal DivideBy = 1m;
        /// <summary>True: luôn ghi dạng text, tránh Excel tự đổi định dạng (số 0 đầu, số thành ngày...).</summary>
        public bool ForceText;
    }
    /// <summary>1 ô ghi text cố định trên mẫu (tiêu đề, header).</summary>
    public sealed class ExcelCellWrite
    {
        /// <summary>Số hàng Excel (1-based).</summary>
        public int Row;
        /// <summary>Tên cột Excel (A, B, C...).</summary>
        public string Column;
        /// <summary>Nội dung ghi vào ô.</summary>
        public string Text;
    }
    /// <summary>1 tiêu chí sắp xếp dữ liệu trước khi ghi Excel.</summary>
    public sealed class ExcelSortField
    {
        /// <summary>Tên cột DataTable; để null khi UseGroupKey = true.</summary>
        public string Field;
        /// <summary>True: so sánh dạng số; False: so sánh chuỗi (bỏ qua khác biệt hoa/thường).</summary>
        public bool Numeric;
        /// <summary>True: tiêu chí này so theo khóa gom nhóm thay vì cột Field.</summary>
        public bool UseGroupKey;
    }
