function Dump-Template($path, $label) {
  $tmp = Join-Path $env:TEMP ("dump_" + [guid]::NewGuid().ToString("N"))
  New-Item -ItemType Directory -Path $tmp | Out-Null
  Copy-Item $path (Join-Path $tmp "m.zip")
  Expand-Archive (Join-Path $tmp "m.zip") -DestinationPath (Join-Path $tmp "x") -Force
  $ss = Get-Content (Join-Path $tmp "x\xl\sharedStrings.xml") -Raw
  $sst = @()
  foreach ($m in [regex]::Matches($ss, '<si>(.*?)</si>', 'Singleline')) { $sst += [regex]::Replace($m.Groups[1].Value, '<[^>]+>', '') }
  $xml = Get-Content (Join-Path $tmp "x\xl\worksheets\sheet1.xml") -Raw
  Write-Output "===== $label ====="
  foreach ($rn in 7,8,10) {
    $rm = [regex]::Match($xml, '<row r="' + $rn + '"[^>]*>(.*?)</row>', 'Singleline')
    if (-not $rm.Success) { continue }
    $cells = [regex]::Matches($rm.Groups[1].Value, '<c r="([A-Z]+)' + $rn + '"[^>]*?(?:/>|>(.*?)</c>)', 'Singleline')
    $line = @()
    foreach ($c in $cells) {
      $col = $c.Groups[1].Value
      $inner = $c.Groups[2].Value
      $txt = ""
      if ($inner -match '<v>(\d+)</v>') { $idx = [int]$matches[1]; if ($idx -lt $sst.Count) { $txt = $sst[$idx] } }
      elseif ($inner -match '<f>(.*?)</f>') { $txt = "=" + $matches[1] }
      $line += ($col + ":" + $txt)
    }
    Write-Output ("row " + $rn + " => " + ($line -join " | "))
  }
}
