function Dump-Rows($path, $label) {
  $tmp = Join-Path $env:TEMP ("dump_" + [guid]::NewGuid().ToString("N"))
  New-Item -ItemType Directory -Path $tmp | Out-Null
  Copy-Item $path (Join-Path $tmp "m.zip")
